15	/**
16	 * Gruppo tag di primo livello, filtrato per tipo di owner via `entity_type`
17	 * (morph alias, es. "product"). Contiene le categorie, che contengono i tag.
18	 * `target` determina il modello taggabile effettivo dei suoi tag:
19	 * - Entity: il record dell'entità (es. Product);
20	 * - Asset:  il Media posseduto da un'entità di quel tipo.
21	 *
22	 * @property int $id
23	 * @property string $entity_type
24	 * @property TagTarget $target
25	 */
26	#[Translatable('name')]
27	class TagGroup extends Model
28	{
29	    use HasGlobalId;
30	    use HasTranslations;
31	
32	    protected $guarded = [];
33	
34	    protected $table = 'tag_groups';
35	
36	    protected $casts = [
37	        'target' => TagTarget::class,
38	    ];
39	
40	    /**
41	     * @return HasMany<TagCategory, $this>
42	     */
43	    public function categories(): HasMany
44	    {
45	        return $this->hasMany(TagCategory::class, 'tag_group_id');
46	    }
47	
48	    /**
49	     * Classe del modello taggabile dai tag di questo gruppo, derivata dal target:
50	     * asset -> Media (config media-library); entity -> modello dell'entità.
51	     *
52	     * @return class-string<Model>
53	     */
54	    public function taggableModelClass(): string
55	    {
56	        if ($this->target === TagTarget::Asset) {
57	            $mediaModel = config('media-library.media_model');
58	            assert(is_string($mediaModel) && is_subclass_of($mediaModel, Model::class));
59	
60	            return $mediaModel;
61	        }
62	
63	        return TaggableEntities::modelClass($this->entity_type);
64	    }
65	}
