5	namespace AtrioTeam\DigitalHub\Tags\Enum;
6	
7	/**
8	 * A cosa si attaccano i tag di un gruppo:
9	 * - Entity: al record dell'entità stessa (Product, Material, …);
10	 * - Asset:  al singolo Media posseduto da un'entità di quel tipo.
11	 *
12	 * In entrambi i casi il gruppo è filtrato per tipo di owner via `entity_type`
13	 * (morph alias); il target determina solo il modello taggabile effettivo.
14	 */
15	enum TagTarget: string
16	{
17	    case Entity = 'entity';
18	    case Asset = 'asset';
19	
20	    public function label(): string
21	    {
22	        $key = 'digital-hub::tag_group.targets.' . $this->value;
23	        $label = __($key);
24	
25	        return is_string($label) && $label !== $key ? $label : ucfirst($this->value);
26	    }
27	
28	    /**
29	     * Opzioni per la Select Filament: [value => label].
30	     *
31	     * @return array<string, string>
32	     */
33	    public static function options(): array
34	    {
35	        $options = [];
36	
37	        foreach (self::cases() as $case) {
38	            $options[$case->value] = $case->label();
39	        }
40	
41	        return $options;
42	    }
43	}
