30	/**
31	 * A simple Filament plugin to configure the panel via this package.
32	 */
33	class DigitalHubPlugin implements Plugin
34	{
35	    public static function make(): static
36	    {
37	        /** @var static $plugin */
38	        $plugin = app(static::class);
39	
40	        return $plugin;
41	    }
42	
43	    public function getId(): string
44	    {
45	        return 'digital-hub';
46	    }
47	
48	    public function register(Panel $panel): void
49	    {
50	        // Pagine di autenticazione con layout "simple" a cui applicare lo
51	        // sfondo custom: login e recupero password (richiesta link + reset).
52	        $authPages = [
53	            Login::class,
54	            RequestPasswordReset::class,
55	            ResetPassword::class,
56	        ];
57	
58	        $panel
59	            ->plugin(MinimalTheme::make())
60	            ->viteTheme('vendor/atrioteam/digital-hub/resources/theme/digital-hub-theme.css')
61	            ->font('Open Sans')
62	            ->pages([
63	                Catalog::class,
64	                AssetManager::class,
65	                ManageGeneralSettings::class,
66	            ])
67	            // Taxonomy tag (gruppo -> categoria -> tag). Le due nidificate restano
68	            // nascoste dalla nav (parent registration): in sidebar solo i gruppi.
69	            ->resources([
70	                TagGroupResource::class,
71	                TagCategoryResource::class,
72	                TagResource::class,
73	            ])
74	            // Voce "Impostazioni" nello user menu (dropdown del badge utente),
75	            // non in sidebar (la pagina ha shouldRegisterNavigation = false).
76	            // Visibile solo a chi può gestire le impostazioni.
77	            ->userMenuItems([
78	                Action::make('settings')
79	                    ->label('Impostazioni')
80	                    ->icon(Heroicon::OutlinedCog6Tooth)
81	                    ->url(fn (): string => ManageGeneralSettings::getUrl())
82	                    ->visible(fn (): bool => ManageGeneralSettings::canAccess()),
83	            ]);
84	
85	
86	
87	        // wrap del form di login in un container
88	        $panel->renderHook(
89	            PanelsRenderHook::SIMPLE_PAGE_START,
90	            fn () => '<div class="afh-login-wrapper">',
91	            scopes: $authPages,
92	        )
93	        ->renderHook(
94	            PanelsRenderHook::SIMPLE_PAGE_END,
95	            fn () => '</div>',
96	            scopes: $authPages,
97	        );
98	
99	        $this->loadSettings($panel, $authPages);
100	
101	
102	    }
103	
104	    public function boot(Panel $panel): void
105	    {
106	        Notifications::alignment(Alignment::Center);
107	
108	        Table::configureUsing(function (Table $table): Table {
109	            return $table->defaultPaginationPageOption(50);
110	        });
111	
112	        DigitalHubTableMacro::register();
113	
114	
115	    }
116	
117	
118	    /**
119	     * @param array<int,class-string> $authPages
120	     */
121	    private function loadSettings(Panel $panel, array $authPages): void
122	    {
123	
124	        // Immagine di sfondo nella schermata di login. Il path è gestito dalla
125	        // pagina Impostazioni (GeneralSettings); se non impostato non viene
126	        // iniettato nulla e resta lo sfondo di default. CSS scoped alla login.
127	        $panel->renderHook(
128	            PanelsRenderHook::HEAD_END,
129	            function (): string|HtmlString {
130	                $settings = app(GeneralSettings::class);
131	
132	                if (blank($settings->login_background_path)) {
133	                    return '';
134	                }
135	
136	                $url = Storage::disk('public')->url($settings->login_background_path);
137	                $overlay = self::overlayRgba($settings->login_overlay_color, $settings->login_overlay_opacity);
138	
139	                return new HtmlString(
140	                    '<style>
141	                        .fi-simple-layout {
142	                            background-image: linear-gradient(' . $overlay . ', ' . $overlay . '), url("' . e($url) . '");
143	                            background-size: cover;
144	                            background-position: center;
145	                            background-repeat: no-repeat;
146	                        }
147	                    </style>',
148	                );
149	            },
150	            scopes: $authPages,
151	        );
152	
153	        // Colore del testo dei button primari (pieni). Gestito dalla pagina
154	        // Impostazioni; override CSS scoped ai soli .fi-color-primary, così non
155	        // tocca i button di altri colori (danger, success, ...). Iniettato su
156	        // tutte le pagine.
157	        $panel->renderHook(
158	            PanelsRenderHook::HEAD_END,
159	            function (): string|HtmlString {
160	                $color = app(GeneralSettings::class)->button_text_color;
161	
162	                if (blank($color)) {
163	                    return '';
164	                }
165	
166	                return new HtmlString(self::buttonTextColorStyle($color));
167	            },
168	        );
169	
170	        // Colore di sfondo dell'area contenuto (parte destra della pagina, non la
171	        // sidebar). Gestito dalla pagina Impostazioni; override CSS su `.fi-body`,
172	        // coperto a sinistra dalla sidebar opaca. Iniettato su tutte le pagine.
173	        $panel->renderHook(
174	            PanelsRenderHook::HEAD_END,
175	            function (): string|HtmlString {
176	                $color = app(GeneralSettings::class)->content_background_color;
177	
178	                if (blank($color)) {
179	                    return '';
180	                }
181	
182	                return new HtmlString(self::contentBackgroundStyle($color));
183	            },
184	        );
185	
186	        // Logo del panel (topbar/brand) gestito dalla pagina Impostazioni
187	        // (GeneralSettings). Se non impostato resta il default di Filament.
188	        $panel
189	            ->brandLogo(function (): string|HtmlString|null {
190	                $settings = app(GeneralSettings::class);
191	
192	                if (blank($settings->panel_logo_path)) {
193	                    return null;
194	                }
195	
196	                $url = Storage::disk('public')->url($settings->panel_logo_path);
197	
198	                return new HtmlString('<img src="' . e($url) . '" alt="' . e(config('app.name')) . '">');
199	            })
200	            ->brandLogoHeight(fn (): ?string => app(GeneralSettings::class)->panel_logo_height);
201	
202	
203	        // Il primary color (che determina anche il colore della voce attiva nella
204	        // sidebar) è gestito dalla pagina Impostazioni. Va impostato qui in
205	        // register() — non è deferibile come logo/sfondo — quindi leggiamo la
206	        // setting con un fallback al config se il DB/settings non è disponibile
207	        // (es. durante le migration o comandi console prima che la tabella esista).
208	        $primaryPalette = self::resolvePrimaryPalette();
209	        if ($primaryPalette !== null) {
210	            $panel->colors([
211	                'primary' => $primaryPalette,
212	            ]);
213	        }
214	
215	
216	
217	    }
218	
219	    /**
220	     * Risolve la palette colori (shade 50..950) da usare come primary del panel.
221	     * Ordine: setting general.primary_color (modalità "palette" = nome costante
222	     * Filament, "custom" = hex libero da cui generare la palette), poi fallback
223	     * sul config. Se la lettura delle settings fallisce (DB/tabella non
224	     * disponibile in console o durante le migration) si ricade sul config senza
225	     * sollevare eccezioni. Ritorna null se non c'è alcun colore configurato.
226	     *
227	     * @return array<int, string>|null
228	     */
229	    private static function resolvePrimaryPalette(): ?array
230	    {
231	        try {
232	            $settings = app(GeneralSettings::class);
233	
234	            if ($settings->primary_color_mode === 'custom') {
235	                if (filled($settings->primary_color_custom)) {
236	                    return \Filament\Support\Colors\Color::hex($settings->primary_color_custom);
237	                }
238	            } elseif (filled($settings->primary_color)) {
239	                return self::paletteFromName($settings->primary_color);
240	            }
241	        } catch (\Throwable) {
242	            // settings non disponibili: si usa il config
243	        }
244	
245	        $fromConfig = config('digital-hub.primary_color');
246	
247	        return is_string($fromConfig) && $fromConfig !== ''
248	            ? self::paletteFromName($fromConfig)
249	            : null;
250	    }
251	
252	    /**
253	     * Restituisce la palette di una costante colore di Filament dato il suo nome
254	     * (es. "Amber"), o null se il nome non corrisponde ad alcuna costante.
255	     *
256	     * @return array<int, string>|null
257	     */
258	    private static function paletteFromName(string $name): ?array
259	    {
260	        if (! defined(\Filament\Support\Colors\Color::class . '::' . $name)) {
261	            return null;
262	        }
263	
264	        /** @var array<int, string> $palette */
265	        $palette = \Filament\Support\Colors\Color::{$name};
266	
267	        return $palette;
268	    }
269	
270	    /**
271	     * Genera il blocco <style> che sovrascrive il colore del testo (e icona) dei
272	     * button primari (pieni). Agisce solo su `.fi-color-primary` non-outlined,
273	     * impostando le variabili CSS del testo di Filament (--text e relativi stati
274	     * hover/dark) con `!important` per battere gli stili inline del componente.
275	     * Lo sfondo dei button resta invariato.
276	     */
277	    private static function buttonTextColorStyle(string $hex): string
278	    {
279	        $text = e($hex);
280	
281	        return '<style>
282	            .fi-btn.fi-color-primary:not(.fi-outlined):not(label) {
283	                --text: ' . $text . ' !important;
284	                --hover-text: ' . $text . ' !important;
285	                --dark-text: ' . $text . ' !important;
286	                --dark-hover-text: ' . $text . ' !important;
287	            }
288	        </style>';
289	    }
290	
291	    /**
292	     * Genera il blocco <style> che sovrascrive il colore di sfondo dell'area
293	     * contenuto (la parte destra della pagina). Agisce su `.fi-body` con
294	     * `!important`, così vale sia in light che in dark mode; la sidebar, opaca,
295	     * copre la sua porzione a sinistra.
296	     */
297	    private static function contentBackgroundStyle(string $hex): string
298	    {
299	        $color = e($hex);
300	
301	        return '<style>
302	            .fi-body {
303	                background-color: ' . $color . ' !important;
304	            }
305	        </style>';
306	    }
307	
308	    /**
309	     * Costruisce una stringa CSS `rgba(...)` per l'overlay della login a partire
310	     * dal colore esadecimale (#rgb o #rrggbb) e dall'opacità (0..1) salvati nelle
311	     * impostazioni. Input non validi degradano a nero/opacità clampata.
312	     */
313	    private static function overlayRgba(string $hex, float $opacity): string
314	    {
315	        $hex = ltrim($hex, '#');
316	
317	        if (strlen($hex) === 3) {
318	            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
319	        }
320	
321	        if (! ctype_xdigit($hex) || strlen($hex) !== 6) {
322	            $hex = '000000';
323	        }
324	
325	        $r = (int) hexdec(substr($hex, 0, 2));
326	        $g = (int) hexdec(substr($hex, 2, 2));
327	        $b = (int) hexdec(substr($hex, 4, 2));
328	        $alpha = max(0.0, min(1.0, $opacity));
329	
330	        return sprintf('rgba(%d, %d, %d, %s)', $r, $g, $b, rtrim(rtrim(number_format($alpha, 2, '.', ''), '0'), '.'));
331	    }
332	
333	}
