7	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
8	use AtrioTeam\DigitalHub\Tags\Models\Tag;
9	use Filament\Forms\Components\Select;
10	
11	/**
12	 * Select dei tag associabili, con vincolo rigido: mostra solo i tag il cui
13	 * gruppo è filtrato per l'entità data e per il target dato (entity|asset),
14	 * raggruppati per categoria negli optgroup. Condiviso fra i form delle entità
15	 * e il picker degli asset nell'AssetManager.
16	 */
17	class TagPicker
18	{
19	    /**
20	     * Picker legato alla relazione `tags` del record del form (entità che usa
21	     * HasTags): Filament sincronizza da sé il pivot `taggables`.
22	     */
23	    public static function make(string $entityAlias, TagTarget $target): Select
24	    {
25	        return self::base($entityAlias, $target)
26	            // HasTags espone tags() come MorphToMany: Filament sincronizza il pivot.
27	            // I tag si gestiscono dalla loro resource, qui si associano solo esistenti.
28	            ->relationship('tags', 'name');
29	    }
30	
31	    /**
32	     * Picker "standalone" (senza relationship): lo stato è un array di id tag.
33	     * Per contesti senza record bindato al form (es. azione nell'AssetManager),
34	     * dove fill/sync sono gestiti a mano dal chiamante.
35	     */
36	    public static function makeStandalone(string $entityAlias, TagTarget $target): Select
37	    {
38	        return self::base($entityAlias, $target);
39	    }
40	
41	    private static function base(string $entityAlias, TagTarget $target): Select
42	    {
43	        return Select::make('tags')
44	            ->label(__('digital-hub::tag.model_plural'))
45	            ->options(fn (): array => self::groupedOptions($entityAlias, $target))
46	            ->multiple()
47	            ->searchable()
48	            ->preload();
49	    }
50	
51	    /**
52	     * Opzioni raggruppate per categoria nel formato optgroup di Filament:
53	     * [categoria => [id => nome]]. Solo i tag dei gruppi (entity_type, target).
54	     *
55	     * @return array<string, array<int, string>>
56	     */
57	    private static function groupedOptions(string $entityAlias, TagTarget $target): array
58	    {
59	        $options = [];
60	
61	        $tags = Tag::query()
62	            ->whereHas('category.group', fn ($query) => $query
63	                ->where('entity_type', $entityAlias)
64	                ->where('target', $target->value))
65	            ->with('category')
66	            ->get();
67	
68	        foreach ($tags as $tag) {
69	            $category = $tag->category !== null ? (string) $tag->category->name : (string) __('digital-hub::tag.ungrouped');
70	            $options[$category][(int) $tag->id] = (string) $tag->name;
71	        }
72	
73	        return $options;
74	    }
75	}
